function hasExpectedTouchSurface(result) {
  if (!result.label.startsWith("touch-")) {
    return true;
  }
  const expectedPage = result.label.startsWith("touch-composed-") ? "Viewport Touch" : "Default Desk";
  const responsiveDeskPassed = (
    result.touchTileMetrics?.tileUnionCoverageRatio >= (expectedPage === "Default Desk" ? 0.55 : 0.9) &&
    result.touchTileMetrics?.columnTrackCount === 12 &&
    result.touchTileMetrics?.rowTrackCount === 8 &&
    result.touchTileMetrics?.columnTrackRatio <= 1.02 &&
    result.touchTileMetrics?.rowTrackRatio <= 1.02 &&
    result.touchTileMetrics?.normalizedTileWidthRatio <= 1.02 &&
    result.touchTileMetrics?.normalizedTileHeightRatio <= 1.02
  );
  const bandReplacementBindings = [
    "all_blackout",
    "blackout",
    "cue_fade_pause",
    "cue_previous",
    "video_blackout",
  ];
  const globalBindingContractPassed = expectedPage === "Default Desk"
    ? result.touchBandReplacementBindings.length === 0
    : bandReplacementBindings.every((binding) => result.touchBandReplacementBindings.includes(binding));
  const sharedUpperLowerLayout =
    result.touchSurfaceWorkspaceFill?.topGap >= -1 &&
    result.touchSurfaceWorkspaceFill?.topGap <= 1 &&
    result.touchSurfaceWorkspaceFill?.bottomGap > 120 &&
    Math.abs(result.touchSurfaceWorkspaceFill?.surfaceToSplitterGap ?? 99) <= 1 &&
    Math.abs(result.touchSurfaceWorkspaceFill?.splitterToBandGap ?? 99) <= 1 &&
    Math.abs(result.touchSurfaceWorkspaceFill?.bandBottomGap ?? 99) <= 1;
  return (
    result.visibleTouchSurfaceCount === 1 &&
    result.visibleTouchModeToggleCount === 2 &&
    result.visibleTouchPageTabCount >= 1 &&
    result.visibleTouchPageAddCount === 1 &&
    result.visibleTouchPageRemoveCount === 1 &&
    result.touchSurfaceMode === "live" &&
    result.touchActivePageLabel === expectedPage &&
    (expectedPage !== "Default Desk" || result.touchDefaultPresetVisible) &&
    result.visibleTouchPlacedControlCount >= 8 &&
    JSON.stringify(result.touchPlacedKinds) === JSON.stringify([
      "Button",
      "ColorWheel",
      "Dial",
      "Fader",
      "Image",
      "IncrementalWheel",
      "Label",
      "XyGrid",
    ]) &&
    result.visibleTouchSafetyDeckCount === 0 &&
    result.visibleTouchGoDeckCount === 0 &&
    result.visibleTouchMasterGridCount === 0 &&
    result.visibleTouchSafetyGuardButtonCount === 0 &&
    globalBindingContractPassed &&
    result.touchTopbarDuplicateControls.length === 0 &&
    sharedUpperLowerLayout &&
    result.visiblePersistentBandCount === 1 &&
    result.visiblePersistentGroupsCount === 1 &&
    result.visiblePersistentStageCount === 1 &&
    result.visiblePersistentContextCount === 1 &&
    result.visibleWorkspaceSplitterCount === 2 &&
    result.visibleControlStageChromeCount === 1 &&
    result.visibleControlStageSelectionListCount === 1 &&
    result.visibleGroupControlFaderWriteHeaderCount === 1 &&
    result.touchComposedCheckPassed &&
    result.touchDocumentAndAppScrollZero &&
    result.touchPlacedUndersizedCount === 0 &&
    result.visibleTouchRemotePanelCount === 0 &&
    result.touchUndersizedTargetCount === 0 &&
    responsiveDeskPassed
  );
}

async function checkEditableTouchSurface(client, expectedPage, expectedDefaultPreset, expectedGroupSelect = false) {
  return await client.evaluate(`(async () => {
    const expectedPage = ${JSON.stringify(expectedPage)};
    const expectedDefaultPreset = ${JSON.stringify(expectedDefaultPreset)};
    const expectedGroupSelect = ${JSON.stringify(expectedGroupSelect)};
    const surface = document.querySelector('[data-touch-surface]');
    const modeButtons = [...document.querySelectorAll('.touchSurfaceModeToggle button')];
    const editButton = modeButtons[0];
    const liveButton = modeButtons[1];
    if (!surface || !editButton || !liveButton) {
      window.__syndocalTouchSurfaceCheck = { passed: false, found: false };
      return false;
    }

    liveButton.click();
    await new Promise((resolveFrame) => requestAnimationFrame(() => requestAnimationFrame(resolveFrame)));
    const initialControls = [...surface.querySelectorAll('[data-touch-control]')];
    const initialControlCount = initialControls.length;
    const initialKinds = [...new Set(initialControls.map((control) => control.getAttribute('data-touch-kind')))].filter(Boolean).sort();
    const initialBindings = [...new Set(initialControls.map((control) => control.getAttribute('data-touch-binding')))].filter(Boolean).sort();
    const bandReplacementBindings = ['all_blackout', 'blackout', 'cue_fade_pause', 'cue_previous', 'video_blackout'];
    const bandReplacementBindingsPresent = bandReplacementBindings.every((binding) => initialBindings.includes(binding));
    const globalBindingContractPassed = expectedGroupSelect
      ? bandReplacementBindingsPresent
      : bandReplacementBindings.every((binding) => !initialBindings.includes(binding));
    const topbarDuplicateControls = initialControls.filter((control) => {
      const binding = control.getAttribute('data-touch-binding');
      const buttonLabel = (control.querySelector('.touchPlacedButton')?.textContent || '').trim().toUpperCase();
      return ['cue_next', 'lighting_master', 'video_master'].includes(binding) || buttonLabel === 'GO';
    }).map((control) => ({
      binding: control.getAttribute('data-touch-binding'),
      label: (control.querySelector('.touchPlacedButton')?.textContent || '').trim(),
    }));
    const operatedKinds = [];

    const groupSelectButton = surface.querySelector('[data-touch-binding="group_select"] .touchPlacedButton:not(:disabled)');
    groupSelectButton?.click();
    await new Promise((resolveFrame) => requestAnimationFrame(() => requestAnimationFrame(resolveFrame)));
    const groupSelectOperationPassed = !expectedGroupSelect ||
      (groupSelectButton instanceof HTMLButtonElement && groupSelectButton.getAttribute('aria-pressed') === 'true');

    const button = surface.querySelector('[data-touch-kind="Button"] .touchPlacedButton:not(:disabled)');
    button?.click();
    if (button) operatedKinds.push('Button');

    for (const kind of ['Fader', 'Dial']) {
      const input = surface.querySelector('[data-touch-kind="' + kind + '"] input[type="range"]:not(:disabled)');
      if (input instanceof HTMLInputElement) {
        input.value = '0.37';
        input.dispatchEvent(new InputEvent('input', { bubbles: true }));
        operatedKinds.push(kind);
      }
    }

    const incremental = surface.querySelector('[data-touch-kind="IncrementalWheel"] button:not(:disabled)');
    incremental?.click();
    if (incremental) operatedKinds.push('IncrementalWheel');

    const color = surface.querySelector('[data-touch-kind="ColorWheel"] input[type="color"]:not(:disabled)');
    if (color instanceof HTMLInputElement) {
      color.value = '#22aa88';
      color.dispatchEvent(new InputEvent('input', { bubbles: true }));
      operatedKinds.push('ColorWheel');
    }

    const xy = surface.querySelector('[data-touch-kind="XyGrid"] .touchPlacedXy:not(:disabled)');
    if (xy) {
      const rect = xy.getBoundingClientRect();
      xy.dispatchEvent(new PointerEvent('pointerdown', {
        bubbles: true,
        pointerId: 91,
        pointerType: 'touch',
        isPrimary: true,
        clientX: rect.left + rect.width * 0.64,
        clientY: rect.top + rect.height * 0.36,
      }));
      operatedKinds.push('XyGrid');
    }

    await new Promise((resolveFrame) => requestAnimationFrame(() => requestAnimationFrame(resolveFrame)));
    const liveActivationKinds = [...surface.querySelectorAll('[data-touch-live-activated="true"]')]
      .map((element) => element.closest('[data-touch-kind]')?.getAttribute('data-touch-kind'))
      .filter(Boolean);
    const liveOperationsPassed = ['Button', 'Fader', 'Dial', 'IncrementalWheel', 'ColorWheel', 'XyGrid']
      .every((kind) => operatedKinds.includes(kind) && liveActivationKinds.includes(kind));

    editButton.click();
    await new Promise((resolveFrame) => requestAnimationFrame(() => requestAnimationFrame(resolveFrame)));
    const paletteLabels = [...document.querySelectorAll('.touchControlPalette button')]
      .map((candidate) => (candidate.textContent || '').trim());
    const expectedPalette = ['Label', 'Image', 'Button', 'Fader', 'Dial', 'Incremental Wheel', 'Color Wheel', 'XY Grid'];
    const editModeSameSurface = document.querySelector('[data-touch-surface]') === surface &&
      surface.getAttribute('data-touch-mode') === 'edit' &&
      surface.querySelectorAll('[data-touch-control]').length === initialControlCount;
    const editHandlesPresent = surface.querySelectorAll('.touchEditMoveHandle').length === initialControlCount &&
      surface.querySelectorAll('.touchEditResizeHandle').length === initialControlCount;
    const pageManagementPresent = document.querySelectorAll('.touchPageTabs button[aria-pressed]').length >= 1 &&
      document.querySelectorAll('.touchPageAdd').length === 1 &&
      document.querySelectorAll('.touchPageRemove').length === 1;
    const bandAbsentInEdit = document.querySelector('.touchSafetyDeck') === null;

    liveButton.click();
    await new Promise((resolveFrame) => requestAnimationFrame(() => requestAnimationFrame(resolveFrame)));
    const liveModeSameSurface = document.querySelector('[data-touch-surface]') === surface &&
      surface.getAttribute('data-touch-mode') === 'live' &&
      surface.querySelectorAll('[data-touch-control]').length === initialControlCount;
    const bandAbsentInLive = document.querySelector('.touchSafetyDeck') === null;
    const activePage = surface.querySelector('.touchSurfaceGrid')?.getAttribute('data-touch-page') ?? '';
    const defaultPresetMatches = surface.getAttribute('data-touch-default-preset') === String(expectedDefaultPreset);
    const palettePassed = JSON.stringify(paletteLabels) === JSON.stringify(expectedPalette);
    const allKindsPresent = JSON.stringify(initialKinds) === JSON.stringify([
      'Button', 'ColorWheel', 'Dial', 'Fader', 'Image', 'IncrementalWheel', 'Label', 'XyGrid'
    ]);
    const layout = document.querySelector('.layoutTouch');
    const layoutRect = layout?.getBoundingClientRect();
    const surfaceRect = surface.getBoundingClientRect();
    const splitter = document.querySelector('[data-workspace-splitter="upper-lower"]');
    const band = document.querySelector('.mappingPersistentWorkspaceBand');
    const splitterRect = splitter?.getBoundingClientRect();
    const bandRect = band?.getBoundingClientRect();
    const sharedUpperLowerLayout = Boolean(layoutRect && splitterRect && bandRect) &&
      Math.abs(surfaceRect.top - layoutRect.top) <= 1 &&
      layoutRect.bottom - surfaceRect.bottom > 120 &&
      Math.abs(splitterRect.top - surfaceRect.bottom) <= 1 &&
      Math.abs(bandRect.top - splitterRect.bottom) <= 1 &&
      Math.abs(layoutRect.bottom - bandRect.bottom) <= 1;
    const persistentLowerBandPresent =
      document.querySelectorAll('.mappingPersistentWorkspaceBand').length === 1 &&
      document.querySelectorAll('[data-persistent-band-part="groups"]').length === 1 &&
      document.querySelectorAll('[data-persistent-band-part="stage"]').length === 1 &&
      document.querySelectorAll('[data-persistent-band-part="context"]').length === 1 &&
      document.querySelectorAll('[data-workspace-splitter]').length === 2;

    window.__syndocalTouchSurfaceCheck = {
      passed:
        activePage === expectedPage &&
        defaultPresetMatches &&
        palettePassed &&
        allKindsPresent &&
        liveOperationsPassed &&
        groupSelectOperationPassed &&
        editModeSameSurface &&
        liveModeSameSurface &&
        editHandlesPresent &&
        pageManagementPresent &&
        globalBindingContractPassed &&
        topbarDuplicateControls.length === 0 &&
        bandAbsentInEdit &&
        bandAbsentInLive &&
        sharedUpperLowerLayout &&
        persistentLowerBandPresent,
      found: true,
      activePage,
      expectedPage,
      defaultPresetMatches,
      paletteLabels,
      palettePassed,
      initialKinds,
      initialBindings,
      allKindsPresent,
      bandReplacementBindingsPresent,
      globalBindingContractPassed,
      topbarDuplicateControls,
      operatedKinds,
      liveActivationKinds,
      liveOperationsPassed,
      expectedGroupSelect,
      groupSelectPresent: groupSelectButton instanceof HTMLButtonElement,
      groupSelectOperationPassed,
      editModeSameSurface,
      liveModeSameSurface,
      editHandlesPresent,
      pageManagementPresent,
      bandAbsentInEdit,
      bandAbsentInLive,
      sharedUpperLowerLayout,
      persistentLowerBandPresent,
    };
    return window.__syndocalTouchSurfaceCheck.passed;
  })()`);
}

function clickLiveAudioControlInPage(kind) {
  const rail = document.querySelector(".videoMixerClipPane > .liveAudioInputBar");
  if (!rail) return false;
  const button = rail.querySelector(
    `[data-live-audio-action="${kind === "refresh" ? "refresh" : "transport"}"]`,
  );
  if (!button || button.disabled) return false;
  button.click();
  return true;
}

async function clickLiveAudioControl(client, kind) {
  return client.evaluate(
    "(" + clickLiveAudioControlInPage.toString() + ")(" + JSON.stringify(kind) + ")",
  );
}

/**
 * The restore contract must be exercised through a trusted input path. A DOM
 * `.click()` would not re-arm the App's native-owner registration fence after
 * the browser fixture startup; this real CDP gesture proves the actual event
 * ordering without widening the mock into a general native-runtime shim.
 */
async function dispatchLiveAudioCdpControlClick(
  client,
  action,
  description,
  { forceDisabledForDirectHandlerProof = false } = {},
) {
  const selector = `.videoMixerClipPane > .liveAudioInputBar [data-live-audio-action="${action}"]`;
  const target = await client.evaluate(`(() => {
    const button = document.querySelector(${JSON.stringify(selector)});
    if (!(button instanceof HTMLButtonElement)) return { found: false };
    const wasDisabled = button.disabled;
    if (${forceDisabledForDirectHandlerProof ? "true" : "false"}) button.disabled = false;
    button.scrollIntoView({ block: "nearest", inline: "nearest" });
    const rect = button.getBoundingClientRect();
    const x = rect.left + rect.width / 2;
    const y = rect.top + rect.height / 2;
    const hit = x >= 0 && x < innerWidth && y >= 0 && y < innerHeight
      ? document.elementFromPoint(x, y)
      : null;
    return {
      found: true,
      enabled: !button.disabled,
      wasDisabled,
      x,
      y,
      width: rect.width,
      height: rect.height,
      centerInViewport: x >= 0 && x < innerWidth && y >= 0 && y < innerHeight,
      topHitOwnsButton: Boolean(hit && (hit === button || button.contains(hit))),
    };
  })()`);
  if (!target.found || !target.enabled || !target.centerInViewport || !target.topHitOwnsButton
    || target.width <= 0 || target.height <= 0) {
    throw new Error(`${description} is not a unique enabled CDP hit target: ${JSON.stringify(target)}`);
  }
  await client.send("Input.dispatchMouseEvent", {
    type: "mouseMoved",
    x: target.x,
    y: target.y,
    button: "none",
    buttons: 0,
  });
  await client.send("Input.dispatchMouseEvent", {
    type: "mousePressed",
    x: target.x,
    y: target.y,
    button: "left",
    buttons: 1,
    clickCount: 1,
  });
  await client.send("Input.dispatchMouseEvent", {
    type: "mouseReleased",
    x: target.x,
    y: target.y,
    button: "left",
    buttons: 0,
    clickCount: 1,
  });
  if (forceDisabledForDirectHandlerProof) {
    await client.evaluate(`(() => {
      const button = document.querySelector(${JSON.stringify(selector)});
      if (button instanceof HTMLButtonElement) button.disabled = ${target.wasDisabled ? "true" : "false"};
    })()`);
  }
  return {
    ...target,
    pointerSequence: "mouseMoved>mousePressed>mouseReleased",
    forcedDirectHandlerProof: forceDisabledForDirectHandlerProof,
  };
}

function setLiveAudioSelectInPage(kind, value) {
  const rail = document.querySelector(".videoMixerClipPane > .liveAudioInputBar");
  if (!rail) return false;
  const select = rail.querySelector(`[data-live-audio-control="${kind}"]`);
  if (!select || select.disabled || ![...select.options].some((option) => option.value === value)) {
    return false;
  }
  select.value = value;
  select.dispatchEvent(new InputEvent("input", { bubbles: true, inputType: "insertReplacementText" }));
  return true;
}

async function setLiveAudioSelect(client, kind, value) {
  return client.evaluate(
    "(" + setLiveAudioSelectInPage.toString() + ")(" +
      JSON.stringify(kind) + "," + JSON.stringify(value) + ")",
  );
}

async function setLiveAudioSelectWhenEnabled(client, kind, value, description) {
  await waitForClientCondition(
    client,
    `(() => {
      const select = document.querySelector('[data-live-audio-control=${JSON.stringify(kind)}]');
      return select instanceof HTMLSelectElement && !select.disabled &&
        [...select.options].some((option) => option.value === ${JSON.stringify(value)});
    })()`,
    `${description} control enablement`,
  );
  const selected = await setLiveAudioSelect(client, kind, value);
  if (!selected) throw new Error(`${description} did not dispatch the exact enabled ${kind} selection ${value}.`);
  return selected;
}

