async function exerciseTimelineSourceShelfProductionPair(client, viewport, recycleClient = null) {
  await client.send('Emulation.setDeviceMetricsOverride', {
    width: viewport.width,
    height: viewport.height,
    deviceScaleFactor: deviceScaleFactorForViewport(viewport),
    mobile: false,
  });
  const openCaptureFixture = async (runId) => {
    const captureUrl = new URL(fixtureUrl('timeline-production-capture'));
    captureUrl.searchParams.set('syndocalTimelineSourceCaptureRun', runId);
    traceViewport(`timeline-source-pair ${runId}-navigate`);
    await client.send('Page.navigate', { url: captureUrl.toString() });
    await waitForApp(client);
    traceViewport(`timeline-source-pair ${runId}-mounted`);
    await clickWorkspaceOption(client, 'control');
    await selectControlSurface(client, 'live');
    await ensureTimelineShowSurface(client);
    await sleep(120);
  };
  await openCaptureFixture('click');
  traceViewport('timeline-source-pair click-start');
  const click = await exerciseTimelineSourceShelfProductionClickPlacement(client);
  traceViewport(`timeline-source-pair click-${click.passed ? 'pass' : 'fail'}`);
  if (recycleClient) {
    client = await recycleClient();
    await client.send('Emulation.setDeviceMetricsOverride', {
      width: viewport.width,
      height: viewport.height,
      deviceScaleFactor: deviceScaleFactorForViewport(viewport),
      mobile: false,
    });
  }
  await openCaptureFixture('drag');
  traceViewport('timeline-source-pair drag-start');
  const drag = await exerciseTimelineSourceShelfProductionDragPlacement(client);
  traceViewport(`timeline-source-pair drag-${drag.passed ? 'pass' : 'fail'}`);
  const parity = Boolean(
    click.passed &&
    drag.passed &&
    click.capture?.transactionCommands?.[1] === 'add_timeline_scene_block' &&
    drag.capture?.transactionCommands?.[1] === 'add_timeline_scene_block' &&
    click.capture?.addArgs?.cueId === drag.capture?.addArgs?.cueId &&
    click.capture?.addArgs?.layerId === drag.capture?.addArgs?.layerId &&
    click.capture?.addArgs?.track === drag.capture?.addArgs?.track
  );
  return [{
    viewport,
    label: `timeline-source-placement-${viewport.width}x${viewport.height}`,
    click,
    drag,
    parity,
    passed: click.passed && drag.passed && parity,
  }, client];
}

async function exerciseTimelinePortalLifecycle(client) {
  await clickControlModeOption(client, 'mixer');
  await sleep(80);
  await clickControlModeOption(client, 'live');
  await sleep(100);
  await ensureTimelineShowSurface(client);
  return client.evaluate(`(() => {
    const host = document.querySelector('[data-timeline-arranger-upper]');
    const arranger = host?.querySelector('.timelineShowSurface');
    const active = document.activeElement;
    return {
      connectedHostCount: [...document.querySelectorAll('[data-timeline-arranger-upper]')].filter((element) => element.isConnected).length,
      connectedArrangerCount: [...document.querySelectorAll('.timelineShowSurface')].filter((element) => element.isConnected).length,
      arrangerInUpperHost: Boolean(host && arranger && host.contains(arranger)),
      deskControlCount: document.querySelectorAll('[data-timeline-arranger-header] [data-timeline-desk-surface]').length,
      focusRestoredToTimelineTab: active?.getAttribute('data-control-mode-option') === 'live',
    };
  })()`);
}

async function runEditIaVideoViewport(client, viewport) {
  await client.send("Emulation.setDeviceMetricsOverride", {
    width: viewport.width,
    height: viewport.height,
    deviceScaleFactor: 1,
    mobile: false,
  });
  await client.send("Page.navigate", { url: fixtureUrl("vj-bank") });
  await waitForApp(client);
  await clickWorkspaceOption(client, "control");
  await clickControlModeOption(client, "mixer");
  await waitForClientCondition(client, `(() =>
    document.querySelector('[data-video-media-library="true"]') &&
    document.querySelectorAll('.videoMediaLibraryItem').length > 0 &&
    document.querySelector('[data-edit-video-preview]') &&
    document.querySelector('[data-edit-video-inspector]')
  )()`, "Edit Video media library and lower panes");

  const navigation = await client.evaluate(`(() => {
    const nav = document.querySelector('[data-edit-domain-navigation]');
    const tabs = [...nav?.querySelectorAll('[role="tab"]') ?? []];
    return {
      tablist: nav?.getAttribute('role') === 'tablist',
      ids: tabs.map((tab) => tab.getAttribute('data-control-mode-option')),
      selectedCount: tabs.filter((tab) => tab.getAttribute('aria-selected') === 'true').length,
      association: tabs.every((tab) => {
        const panel = document.getElementById(tab.getAttribute('aria-controls') || '');
        return Boolean(panel && panel.getAttribute('role') === 'tabpanel' && panel.getAttribute('aria-labelledby') === tab.id);
      }),
    };
  })()`);
  await client.evaluate(`document.getElementById('edit-domain-tab-mixer')?.focus()`);
  await pressKey(client, "ArrowLeft");
  await sleep(48);
  const keyboardLighting = await client.evaluate(`document.activeElement?.getAttribute('data-control-mode-option') === 'edit'`);
  await pressKey(client, "ArrowRight");
  await sleep(48);
  const keyboardVideo = await client.evaluate(`document.activeElement?.getAttribute('data-control-mode-option') === 'mixer'`);

  const selected = await client.evaluate(`(() => {
    const asset = document.querySelector('.videoMediaLibraryItem');
    asset?.dispatchEvent(new MouseEvent('click', { bubbles: true }));
    return asset?.getAttribute('aria-label') ?? '';
  })()`);
  await waitForClientCondition(client, `(() => {
    const preview = document.querySelector('[data-edit-video-preview]');
    const inspector = document.querySelector('[data-edit-video-inspector]');
    return Boolean(preview?.querySelector('.editVideoPreviewContent')) &&
      Boolean(inspector?.querySelector('.editVideoInspectorContent'));
  })()`, "Selected Edit Video media properties");
  const layout = await client.evaluate(`(() => {
    const visible = (element) => {
      if (!(element instanceof HTMLElement)) return false;
      const rect = element.getBoundingClientRect();
      const style = getComputedStyle(element);
      return rect.width > 0 && rect.height > 0 && style.display !== 'none' && style.visibility !== 'hidden';
    };
    const rect = (element) => {
      if (!(element instanceof HTMLElement)) return null;
      const box = element.getBoundingClientRect();
      return {
        left: box.left,
        top: box.top,
        right: box.right,
        bottom: box.bottom,
        width: box.width,
        height: box.height,
      };
    };
    const contains = (outer, inner) => Boolean(
      outer && inner &&
      inner.left >= outer.left - 1 &&
      inner.top >= outer.top - 1 &&
      inner.right <= outer.right + 1 &&
      inner.bottom <= outer.bottom + 1
    );
    const intersects = (left, right) => Boolean(
      left && right &&
      right.right > left.left + 1 && right.left < left.right - 1 &&
      right.bottom > left.top + 1 && right.top < left.bottom - 1
    );
    const app = document.querySelector('.app');
    const upper = document.querySelector('[data-workspace-pane="upper"]');
    const library = document.querySelector('[data-video-media-library="true"]');
    const libraryHeader = library?.querySelector(':scope > .panelHeader');
    const clipPane = library?.querySelector('.videoMixerClipPane');
    const librarySurface = library?.querySelector('.videoMediaLibrarySurface');
    const importDisclosure = library?.querySelector('[data-edit-video-import-disclosure]');
    const importSummary = importDisclosure?.querySelector('summary');
    const preview = document.querySelector('[data-edit-video-preview]');
    const inspector = document.querySelector('[data-edit-video-inspector]');
    const advanced = inspector?.querySelector('.editVideoAdvancedDisclosure');
    const cards = [...document.querySelectorAll('.videoMediaLibraryItem')];
    const firstVisibleCard = cards.find(visible) ?? null;
    const upperRect = rect(upper);
    const libraryRect = rect(library);
    const clipPaneRect = rect(clipPane);
    const librarySurfaceRect = rect(librarySurface);
    const libraryHeaderRect = rect(libraryHeader);
    const importSummaryRect = rect(importSummary);
    const cardRect = rect(firstVisibleCard);
    const primaryViewport = innerWidth >= 1_600 && innerHeight >= 900;
    const requiredUpperHeight = primaryViewport ? 280 : 220;
    const requiredLibraryHeight = primaryViewport ? 180 : 120;
    const requiredCardHeight = primaryViewport ? 72 : 48;
    return {
      libraryVisible: visible(library),
      previewVisible: visible(preview),
      inspectorVisible: visible(inspector),
      upperRect,
      libraryRect,
      clipPaneRect,
      librarySurfaceRect,
      libraryHeaderRect,
      importSummaryRect,
      cardRect,
      upperHasMinimumHeight: Boolean(upperRect && upperRect.height >= requiredUpperHeight),
      libraryOccupiesOnlyUpperPane: contains(upperRect, libraryRect) && Boolean(
        upperRect && libraryRect && libraryRect.height >= upperRect.height - 24
      ),
      clipPaneUsesEffectiveHeight: contains(libraryRect, clipPaneRect) && Boolean(
        clipPaneRect && clipPaneRect.height >= requiredLibraryHeight
      ),
      librarySurfaceVisible: visible(librarySurface),
      librarySurfaceIsInFlow: getComputedStyle(librarySurface ?? document.body).position !== 'absolute',
      librarySurfaceContainedInClipPane: contains(clipPaneRect, librarySurfaceRect),
      librarySurfaceUsesEffectiveHeight: Boolean(
        librarySurfaceRect && librarySurfaceRect.height >= requiredLibraryHeight
      ),
      firstCardVisibleInCatalogViewport: visible(firstVisibleCard) && intersects(librarySurfaceRect, cardRect),
      cardUsesMinimumHeight: Boolean(cardRect && cardRect.height >= requiredCardHeight),
      importDisclosureVisible: visible(importDisclosure),
      importDisclosureClosed: importDisclosure instanceof HTMLDetailsElement && !importDisclosure.open,
      importSummaryIsReachable: visible(importSummary) && contains(libraryHeaderRect, importSummaryRect) && Boolean(
        importSummaryRect && importSummaryRect.height >= 44
      ),
      advancedDisclosure: advanced instanceof HTMLDetailsElement && !advanced.open,
      selectedCardCount: cards.filter((card) => card.classList.contains('selected')).length,
      thumbnailTruthful: Boolean(preview?.querySelector('img, .videoMediaLibraryThumbnailPlaceholder')) &&
        /Thumbnail/.test(preview?.querySelector('h2')?.textContent || ''),
      cardHitTarget: Math.min(...cards.map((card) => card.getBoundingClientRect().height)),
      documentAndAppScrollZero: document.documentElement.scrollWidth <= innerWidth + 1 &&
        document.body.scrollWidth <= document.body.clientWidth + 1 &&
        (!app || app.scrollWidth <= app.clientWidth + 1),
    };
  })()`);
  let screenshotVerification = null;
  if (controlScreenshotDir) {
    mkdirSync(controlScreenshotDir, { recursive: true });
    screenshotVerification = await captureSettledViewport(
      client,
      join(controlScreenshotDir, `control-edit-video-${viewport.width}x${viewport.height}.png`),
    );
  }
  await client.send("Page.navigate", { url: fixtureUrl("vj-empty") });
  await waitForApp(client);
  await clickWorkspaceOption(client, "control");
  await clickControlModeOption(client, "mixer");
  await waitForClientCondition(client, `Boolean(document.querySelector('[data-video-media-library="true"]'))`, "Empty Edit Video media library");
  const emptyLibraryImport = await client.evaluate(`(() => {
    const library = document.querySelector('[data-video-media-library="true"]');
    const disclosure = library?.querySelector('[data-edit-video-import-disclosure]');
    const summary = disclosure?.querySelector('summary');
    const visible = (element) => {
      if (!(element instanceof HTMLElement)) return false;
      const rect = element.getBoundingClientRect();
      const style = getComputedStyle(element);
      return rect.width > 0 && rect.height > 0 && style.display !== 'none' && style.visibility !== 'hidden';
    };
    return {
      assetCardCount: library?.querySelectorAll('.videoMediaLibraryItem').length ?? -1,
      disclosureVisible: visible(disclosure),
      disclosureClosed: disclosure instanceof HTMLDetailsElement && !disclosure.open,
      summaryVisible: visible(summary),
      summaryHeight: summary instanceof HTMLElement ? summary.getBoundingClientRect().height : 0,
      sourceCreateSurfacePresent: Boolean(disclosure?.querySelector('[data-edit-video-import-surface]')),
    };
  })()`);
  const checks = {
    exactDomainTablist: navigation.tablist && JSON.stringify(navigation.ids) === JSON.stringify(['edit', 'mixer', 'live']) && navigation.selectedCount === 1 && navigation.association,
    domainKeyboardRoving: keyboardLighting && keyboardVideo,
    mediaLibraryUpperOnly: layout.libraryVisible,
    mediaLibraryOwnsUsableUpperPane: layout.upperHasMinimumHeight && layout.libraryOccupiesOnlyUpperPane,
    mediaLibraryCatalogIsInFlowAndContained: layout.clipPaneUsesEffectiveHeight &&
      layout.librarySurfaceVisible &&
      layout.librarySurfaceIsInFlow &&
      layout.librarySurfaceContainedInClipPane &&
      layout.librarySurfaceUsesEffectiveHeight,
    mediaLibraryCardsAreVisibleInUsableCatalog: layout.firstCardVisibleInCatalogViewport && layout.cardUsesMinimumHeight,
    mediaLibraryImportIsAlwaysReachableFromTheHeader: layout.importDisclosureVisible &&
      layout.importDisclosureClosed && layout.importSummaryIsReachable,
    emptyMediaLibraryStillExposesClosedImportControl: emptyLibraryImport.assetCardCount === 0 &&
      emptyLibraryImport.disclosureVisible && emptyLibraryImport.disclosureClosed &&
      emptyLibraryImport.summaryVisible && emptyLibraryImport.summaryHeight >= 44 &&
      emptyLibraryImport.sourceCreateSurfacePresent,
    selectedMediaDrivesThumbnailAndProperties: selected.length > 0 && layout.previewVisible && layout.inspectorVisible && layout.selectedCardCount === 1 && layout.thumbnailTruthful,
    advancedControlsAreClosedDisclosure: layout.advancedDisclosure,
    mediaCardsKeepUsableHitTargets: layout.cardHitTarget >= 24,
    documentAndAppScrollZero: layout.documentAndAppScrollZero,
  };
  const failedChecks = Object.entries(checks).filter(([, passed]) => !passed).map(([name]) => name);
  return {
    label: `edit-ia-video-${viewport.width}x${viewport.height}`,
    passed: failedChecks.length === 0,
    checks,
    failedChecks,
    navigation,
    layout,
    emptyLibraryImport,
    screenshotVerification,
  };
}

async function runTimelineSlimViewport(client, viewport, recycleClient = null) {
  await client.send('Emulation.setDeviceMetricsOverride', {
    width: viewport.width,
    height: viewport.height,
    deviceScaleFactor: deviceScaleFactorForViewport(viewport),
    mobile: false,
  });
  // The persistent Timeline domain owns its arranger and source shelf. Scene
  // Matrix remains in Lighting, so this focused proof must not navigate via
  // the old cross-domain drag surface.
  const sceneMatrix = {
    before: { documentAndAppScrollZero: true },
    after: { documentAndAppScrollZero: true },
    subThresholdClick: null,
    oneGestureDrag: null,
    failedChecks: [],
  };
  // Cover both persisted authored layers and the implicit two-layer projection
  // used by new / legacy .sdc projects. T15 must present the same operator
  // contract on both data shapes.
  await client.send('Page.navigate', { url: fixtureUrl('timeline-layered') });
  await waitForApp(client);
  await clickWorkspaceOption(client, 'control');
  await selectControlSurface(client, 'live');
  await setTimelineToolsDisclosureOpen(client, true);
  await ensureTimelineShowSurface(client);
  await sleep(120);
  const initialShelfState = await readTimelineInitialShelfState(client);
  const visual = await measureTimelineSlimVisual(client);
  await showTimelineSourceShelfMedia(client);
  const sourceShelf = await measureTimelineSourceShelf(client);
  const sourceShelfFocus = await focusTimelineSourceShelf(client);
  const sourceShelfContextSwitch = await exerciseTimelineSourceShelfContextSwitch(client);
  const portalLifecycle = await exerciseTimelinePortalLifecycle(client);
  await setTimelineToolsDisclosureOpen(client, true);
  await ensureTimelineShowSurface(client);
  const deskSurfaceAria = await exerciseTimelineDeskSurfaceAria(client);
  const laneCountStability = await exerciseTimelineLaneCountStability(client);
  const blockKeyboardFocus = await exerciseTimelineBlockKeyboardFocusVisual(client);
  await setTimelineToolsDisclosureOpen(client, false);
  const blockPropertiesDrawer = await exerciseTimelineBlockPropertiesDrawerLayout(client);
  const laneMenuKeyboard = await exerciseTimelineLaneMenuKeyboard(client);
  const dialogEscapePriority = await exerciseTimelineDialogEscapePriority(client);
  const escapePriority = await exerciseTimelineSlimEscapePriority(client);
  if (recycleClient) {
    client = await recycleClient();
    await client.send('Emulation.setDeviceMetricsOverride', {
      width: viewport.width,
      height: viewport.height,
      deviceScaleFactor: deviceScaleFactorForViewport(viewport),
      mobile: false,
    });
  }
  const [sourceShelfProductionPair, activeClient] = await exerciseTimelineSourceShelfProductionPair(
    client,
    viewport,
    recycleClient,
  );
  client = activeClient;
  if (recycleClient) {
    client = await recycleClient();
    await client.send('Emulation.setDeviceMetricsOverride', {
      width: viewport.width,
      height: viewport.height,
      deviceScaleFactor: deviceScaleFactorForViewport(viewport),
      mobile: false,
    });
  }
  const sourceShelfScenePlacement = sourceShelfProductionPair.click;
  const sourceShelfSceneDragPlacement = sourceShelfProductionPair.drag;
  const sourceShelfPlacementParity = sourceShelfProductionPair.parity;
  await client.send('Page.navigate', { url: fixtureUrl('timeline') });
  await waitForApp(client);
  await clickWorkspaceOption(client, 'control');
  await selectControlSurface(client, 'live');
  await setTimelineToolsDisclosureOpen(client, true);
  await ensureTimelineShowSurface(client);
  await sleep(120);
  const implicitVisual = await measureTimelineSlimVisual(client);
  const expectedDeskSurfaceIds = ['automation', 'playback', 'show'];
  const expectedTimelineToolIds = [
    'arm-cue',
    'block-properties',
    'fit-all',
    'magnet',
    'pan-next',
    'pan-prev',
    'reveal-playhead',
    'reveal-selected',
    'stretch-rate',
    'stretch-window',
    'super-scene',
    'zoom-in',
    'zoom-out',
  ];
  const conditions = [
    ['timelineSlimRemovesDuplicateCuesDeskTab', () => visual.cuesDeskTabCount === 0],
    ['timelineSlimUsesExactDeskSurfaceSetAndAriaState', () =>
      JSON.stringify([...visual.deskTabSurfaceIds].sort()) === JSON.stringify(expectedDeskSurfaceIds) &&
      visual.deskTabPressedStates.filter((value) => value === 'true').length === 1 &&
      visual.deskTabActiveStates.filter(Boolean).length === 1 &&
      deskSurfaceAria.passed],
    ['timelineSlimToolbarsUseNamedIconToggles', () =>
      visual.toolbarRootCount >= 1 &&
      visual.toolbarButtonCount === expectedTimelineToolIds.length &&
      visual.toolbarAriaButtonCount === visual.toolbarButtonCount &&
      visual.toolbarIconOnlyButtonCount === visual.toolbarButtonCount &&
      visual.toolbarOverflowCount === 0],
    ['timelineSlimPreservesExactToolInventory', () =>
      visual.toolbarToolIds.length === expectedTimelineToolIds.length &&
      new Set(visual.toolbarToolIds).size === expectedTimelineToolIds.length &&
      JSON.stringify([...visual.toolbarToolIds].sort()) === JSON.stringify(expectedTimelineToolIds)],
    ['timelineSlimBlockPropertiesDrawerIsDockedReachableAndContained', () => blockPropertiesDrawer.passed],
    ['timelineSlimLaneCountsStayStableAcrossZoomAndPan', () => laneCountStability.passed],
    ['timelineSlimKeyboardFocusKeepsVisibleWhiteStroke', () => blockKeyboardFocus.passed],
    ['timelineSlimGuttersUseExactlyNumberExpandEyeLock', () =>
      visual.gutterCount > 0 && visual.gutterRows.every((row) => row.exactFourElements)],
    ['timelineSlimLaneMenuSupportsKeyboardAndReturnsFocus', () => laneMenuKeyboard.passed],
    ['timelineSlimDialogEscapePrecedesDrawerAndReturnsFocus', () => dialogEscapePriority.passed],
    ['timelineSlimGutterTypeUsesColorOrIconNotText', () =>
      visual.visibleGutterNameCount === 0 && visual.gutterKindCount >= 2 &&
      visual.sectionKindSummaries.length >= 2 &&
      new Set(visual.sectionKindSummaries.map((entry) => entry.name)).size === visual.sectionKindSummaries.length &&
      visual.sectionKindSummaries.every((entry) =>
        entry.kind.length > 0 && entry.name.toLowerCase().includes(entry.kind.toLowerCase()))],
    ['timelineSlimImplicitLayersUseSameGutterContract', () =>
      implicitVisual.gutterCount === 2 &&
      implicitVisual.gutterRows.every((row) => row.exactFourElements) &&
      implicitVisual.visibleGutterNameCount === 0 &&
      implicitVisual.gutterKindCount === 2],
    ['timelineSlimBlocksAreThick', () =>
      visual.blockCount > 0 && visual.thickBlockCount === visual.blockCount && visual.minBlockHeight >= 26],
    ['timelineSlimBlocksUseSolidIdentityFill', () =>
      visual.blockCount > 0 &&
      visual.identityFillCount === visual.blockCount &&
      visual.solidIdentityBandCount === visual.blockCount],
    ['timelineSlimBlocksUseOpaqueBlackBorder', () =>
      visual.blockCount > 0 && visual.opaqueBlackBorderCount === visual.blockCount],
    ['timelineSlimBlocksShowNameAndDurationOnTwoLines', () =>
      visual.twoLineEligibleCount > 0 &&
      visual.twoLineBlockCount === visual.twoLineEligibleCount &&
      visual.minTwoLineFontPx >= 10],
    ['timelineSlimImplicitLayersUseSameBlockContract', () =>
      implicitVisual.blockCount > 0 &&
      implicitVisual.thickBlockCount === implicitVisual.blockCount &&
      implicitVisual.identityFillCount === implicitVisual.blockCount &&
      implicitVisual.opaqueBlackBorderCount === implicitVisual.blockCount &&
      implicitVisual.twoLineBlockCount === implicitVisual.twoLineEligibleCount],
    ['timelineSlimGridLinesStayDimmed', () =>
      visual.minorGridLineCount > 0 &&
      visual.majorGridLineCount > 0 &&
      visual.dividerLineCount > 0 &&
      visual.maxMinorGridInk <= 0.085 &&
      visual.maxMajorGridInk <= 0.14 &&
      visual.maxDividerInk <= 0.09],
    ['timelineSlimKeepsLightingMatrixOutOfTimelineDomain', () =>
      visual.gutterCount > 0 && sourceShelf.present],
    ['timelineSlimUsesShelfInsteadOfCrossDomainMatrixDrag', () =>
      sourceShelf.present && sourceShelf.categoryButtonCount === 2 && sourceShelf.filterCount === 3],
    ['timelineSourceShelfSceneClickPlacesExactlyOneBlockOnSelectedVisibleLane', () =>
      sourceShelfScenePlacement.passed],
    ['timelineSourceShelfSceneDragHitsVisibleLaneAndPlacesExactlyOneBlock', () =>
      sourceShelfSceneDragPlacement.passed],
    ['timelineSourceShelfDragAndClickUseSameRegisteredScenePlacementMeaning', () =>
      sourceShelfPlacementParity],
    ['timelineSlimKeepsDocumentAndAppScrollZero', () =>
      visual.documentAndAppScrollZero &&
      implicitVisual.documentAndAppScrollZero],
    ['timelineSourceShelfIsContainedAndUsesLocalScroll', () =>
      sourceShelf.present && sourceShelf.contained && sourceShelf.scrollSurfaces.every((surface) => surface.permitsInternalScroll)],
    ['timelineSourceShelfExposesExactSourceAndTargetControls', () =>
      sourceShelf.categoryButtonCount === 2 && sourceShelf.filterCount === 3 &&
      initialShelfState?.sourceKinds.includes('Lighting') &&
      sourceShelf.sourceKinds.includes('Video') && sourceShelf.sourceKinds.includes('Audio') &&
      sourceShelf.placementButtonCount >= 2 &&
      sourceShelf.targetOptions.every((count) => count > 0) &&
      sourceShelf.targetValues.every((value) => /^\d+$/.test(value)) &&
      sourceShelf.sourceKinds.every((kind) => ["Lighting", "Video", "Audio"].includes(kind))],
    ['timelineSourceShelfControlsAreFocusableAndHitSized', () => sourceShelfFocus && sourceShelf.minHitTarget >= 24],
    ['timelineSourceShelfSwitchesSourcesAndInspectorWithPressedState', () => sourceShelfContextSwitch.passed],
    ['timelineReloadDefaultsToUnselectedSources', () => Boolean(initialShelfState?.sourcesSelected && initialShelfState.inspectorSelected && initialShelfState.inspectorAbsent && initialShelfState.sourceBodyPresent)],
    ['timelinePortalReopensOneConnectedArrangerAndRestoresTabFocus', () => portalLifecycle.connectedHostCount === 1 && portalLifecycle.connectedArrangerCount === 1 && portalLifecycle.arrangerInUpperHost && portalLifecycle.deskControlCount === 3 && portalLifecycle.focusRestoredToTimelineTab],
    ['timelineSourceShelfKeepsDocumentAndAppScrollZero', () => sourceShelf.documentAndAppScrollZero],
    ['timelineSlimEscapeClosesToolMenuBeforeLeavingTimeline', () => escapePriority.passed],
  ];
  const checks = Object.fromEntries(conditions.map(([name, check]) => {
    try { return [name, Boolean(check())]; } catch { return [name, false]; }
  }));
  const failedChecks = Object.entries(checks)
    .filter(([, passed]) => !passed)
    .map(([name]) => name);
  return {
    viewport,
    label: `timeline-slim-${viewport.width}x${viewport.height}`,
    passed: failedChecks.length === 0,
    checks,
    failedChecks,
    visual,
    implicitVisual,
    sourceShelf,
    sourceShelfScenePlacement,
    sourceShelfSceneDragPlacement,
    sourceShelfPlacementParity,
    sourceShelfFocus,
    sourceShelfContextSwitch,
    initialShelfState,
    portalLifecycle,
    deskSurfaceAria,
    blockPropertiesDrawer,
    laneCountStability,
    blockKeyboardFocus,
    laneMenuKeyboard,
    dialogEscapePriority,
    t14: {
      subThresholdClick: sceneMatrix.subThresholdClick,
      oneGestureDrag: sceneMatrix.oneGestureDrag,
      failedChecks: sceneMatrix.failedChecks.filter((name) =>
        name.includes('SubThreshold') || name.includes('OneGestureDrag') || name.includes('DragDoesNotRecall')),
    },
    escapePriority,
  };
}

async function runCueRecallViewport(client, viewport) {
  await openCueFixture(client, viewport, "cue-recall");
  const cueStoreRoute = await client.evaluate(`(() => {
    const isVisible = (element) => {
      if (!(element instanceof HTMLElement)) return false;
      const rect = element.getBoundingClientRect();
      const style = getComputedStyle(element);
      return rect.width > 0 && rect.height > 0
        && style.display !== 'none' && style.visibility !== 'hidden';
    };
    const pane = document.querySelector('[data-scene-settings]');
    const details = document.querySelector('[data-scene-details]');
    const drawer = document.querySelector('[data-timeline-context-drawer-panel="cue"]');
    const form = document.querySelector('[data-cue-update-source-form]');
    const select = form?.querySelector('select');
    return {
      paneVisible: isVisible(pane),
      detailsVisible: isVisible(details),
      drawerVisible: isVisible(drawer),
      formVisible: isVisible(form),
      effectsOptionPresent: select instanceof HTMLSelectElement
        && [...select.options].some((option) => option.value === 'effects'),
    };
  })()`);
  await selectVisibleOption(client, "[data-cue-update-source-form] select", "effects");
  await sleep(120);
  await clickVisibleByText(client, ".cueItem .cueEffectRecallEditor > summary", "Effect Recall");
  await sleep(80);
  await clickVisibleByText(client, ".cueItem .cueEffectRecallToolbar .buttonRow button", "Clear");
  await sleep(120);
  const stepExercise = await client.evaluate(`(async () => {
    const raf2 = () => new Promise((resolveFrame) => requestAnimationFrame(() => requestAnimationFrame(resolveFrame)));
    const editor = document.querySelector('.cueItem [data-cue-step-editor]');
    if (!(editor instanceof HTMLDetailsElement)) return null;
    editor.open = true;
    editor.scrollIntoView({ block: 'center', inline: 'nearest' });
    await raf2();
    const initialRows = [...editor.querySelectorAll('[data-cue-step-index]')];
    const initialFadeValues = initialRows.map((row) => Number(row.querySelector('[data-cue-step-fade]')?.value));
    const initialHoldValues = initialRows.map((row) => Number(row.querySelector('[data-cue-step-hold]')?.value));
    const initialTotalLabel = (editor.querySelector('summary small')?.textContent || '').trim();
    editor.querySelectorAll('[data-cue-step-duplicate]')[0]?.click();
    await raf2();
    const firstFade = editor.querySelectorAll('[data-cue-step-fade]')[0];
    if (firstFade instanceof HTMLInputElement) {
      firstFade.value = '375';
      firstFade.dispatchEvent(new Event('input', { bubbles: true }));
    }
    await raf2();
    editor.querySelectorAll('[data-cue-step-down]')[0]?.click();
    await raf2();
    editor.querySelector('[data-cue-step-add]')?.click();
    await raf2();
    editor.querySelector('[data-cue-step-use-beats]')?.click();
    await raf2();
    return {
      initialCount: initialRows.length,
      initialFadeValues,
      initialHoldValues,
      initialTotalLabel,
    };
  })()`);
  const actionReached = await client.evaluate(`(() => {
    const action = document.querySelector('.cueItem .cueSaveRecall');
    if (!action) return false;
    action.scrollIntoView({ block: 'center', inline: 'nearest' });
    return true;
  })()`);
  await sleep(120);
  const containment = await measure(client, `cue-recall-${viewport.width}x${viewport.height}`);
  const stats = await client.evaluate(`(() => {
    const panel = document.querySelector('.cuePanel');
    const panelRect = panel?.getBoundingClientRect();
    const actions = [...document.querySelectorAll('.cueItem .cueSaveDetails, .cueItem .cueSaveRecall, .cueItem .cueUpdateLook')];
    const fullyVisible = (element) => {
      if (!element || !panelRect) return false;
      const rect = element.getBoundingClientRect();
      const style = getComputedStyle(element);
      return style.display !== 'none' && style.visibility !== 'hidden' &&
        rect.width > 0 && rect.height > 0 &&
        rect.left >= Math.max(0, panelRect.left) && rect.right <= Math.min(innerWidth, panelRect.right) &&
        rect.top >= Math.max(0, panelRect.top) && rect.bottom <= Math.min(innerHeight, panelRect.bottom);
    };
    const saveDetails = document.querySelector('.cueItem .cueSaveDetails');
    const saveRecall = document.querySelector('.cueItem .cueSaveRecall');
    const updateLook = document.querySelector('.cueItem .cueUpdateLook');
    const recallDetails = document.querySelector('.cueItem .cueEffectRecallEditor');
    const stepEditor = document.querySelector('.cueItem [data-cue-step-editor]');
    const stepList = stepEditor?.querySelector('.cueStepList');
    const stepRows = [...(stepEditor?.querySelectorAll('[data-cue-step-index]') ?? [])];
    const authoredBeats = document.querySelector('.cueItem [data-cue-authored-beats]');
    return {
      scope: document.querySelector('[data-cue-update-source-form] select')?.value ?? '',
      recallDetailsOpen: Boolean(recallDetails?.open),
      recallElementCount: document.querySelectorAll('.cueItem .cueEffectRecallEditor').length,
      recallCount: (recallDetails?.querySelector('summary small')?.textContent || '').trim(),
      saveDetailsLabel: (saveDetails?.textContent || '').trim(),
      saveRecallLabel: (saveRecall?.textContent || '').trim(),
      updateLookLabel: (updateLook?.textContent || '').trim(),
      saveDetailsDisabled: Boolean(saveDetails?.disabled),
      saveRecallDisabled: Boolean(saveRecall?.disabled),
      updateLookDisabled: Boolean(updateLook?.disabled),
      actionCount: actions.length,
      fullyVisibleActionCount: actions.filter(fullyVisible).length,
      stepEditorOpen: Boolean(stepEditor?.open),
      stepCount: stepRows.length,
      stepFadeValues: stepRows.map((row) => Number(row.querySelector('[data-cue-step-fade]')?.value)),
      stepHoldValues: stepRows.map((row) => Number(row.querySelector('[data-cue-step-hold]')?.value)),
      stepTotalLabel: (stepEditor?.querySelector('summary small')?.textContent || '').trim(),
      stepDerivedLabel: (stepEditor?.querySelector('.cueStepToolbar span')?.textContent || '').trim(),
      stepListOverflowY: stepList ? getComputedStyle(stepList).overflowY : '',
      addButtonCount: stepEditor?.querySelectorAll('[data-cue-step-add]').length ?? 0,
      duplicateButtonCount: stepEditor?.querySelectorAll('[data-cue-step-duplicate]').length ?? 0,
      upButtonCount: stepEditor?.querySelectorAll('[data-cue-step-up]').length ?? 0,
      downButtonCount: stepEditor?.querySelectorAll('[data-cue-step-down]').length ?? 0,
      fadeInputCount: stepEditor?.querySelectorAll('[data-cue-step-fade]').length ?? 0,
      holdInputCount: stepEditor?.querySelectorAll('[data-cue-step-hold]').length ?? 0,
      saveStepsEnabled: !Boolean(stepEditor?.querySelector('[data-cue-step-save]')?.disabled),
      authoredBeatsValue: authoredBeats instanceof HTMLInputElement ? Number(authoredBeats.value) : null,
      // T7: the cue edit row carries the identity color picker.
      cueColorInputCount: document.querySelectorAll('.cueItem [data-cue-color-input]').length,
    };
  })()`);
  if (shouldCaptureViewport(viewport)) {
    mkdirSync(screenshotDir, { recursive: true });
    const screenshot = await client.send("Page.captureScreenshot", { format: "png", fromSurface: true });
    writeFileSync(
      join(screenshotDir, `cue-recall-open-${viewport.width}x${viewport.height}.png`),
      screenshot.data,
      "base64",
    );
  }
  const conditions = [
    ["cueActionReached", () => actionReached],
    ["cueNoOuterOverflow", () => hasNoOuterOverflow(containment)],
    ["cueDetailsIntegratedInSceneSettings", () => cueStoreRoute.paneVisible && cueStoreRoute.detailsVisible],
    ["standaloneCueEditorAbsent", () => !cueStoreRoute.drawerVisible],
    ["cueUpdateSourceFormReached", () => cueStoreRoute.formVisible],
    ["cueEffectsScopeOptionPresent", () => cueStoreRoute.effectsOptionPresent],
    ["cueEffectsScopeSelected", () => stats.scope === "effects"],
    ["cueEffectRecallOpen", () => stats.recallDetailsOpen],
    ["cueEffectRecallElementRendered", () => stats.recallElementCount === 1],
    ["cueEffectRecallCleared", () => stats.recallCount === "0 / 1"],
    ["cueSaveDetailsLabel", () => stats.saveDetailsLabel === "Save Details"],
    ["cueSaveRecallLabel", () => stats.saveRecallLabel === "Save Recall"],
    ["cueUpdateLookLabel", () => stats.updateLookLabel === "Update Look"],
    ["cueSaveDetailsEnabled", () => !stats.saveDetailsDisabled],
    ["cueSaveRecallEnabled", () => !stats.saveRecallDisabled],
    ["cueUpdateLookEnabled", () => !stats.updateLookDisabled],
    ["cueThreeActionsRendered", () => stats.actionCount === 3],
    ["cueThreeActionsVisible", () => stats.fullyVisibleActionCount === 3],
    ["cueThreeStepFixtureLoaded", () => stepExercise?.initialCount === 3],
    ["cueStepFixtureFadeValues", () => JSON.stringify(stepExercise?.initialFadeValues) === JSON.stringify([250, 500, 1000])],
    ["cueStepFixtureHoldValues", () => JSON.stringify(stepExercise?.initialHoldValues) === JSON.stringify([750, 500, 250])],
    ["cueStepFixtureTotal", () => stepExercise?.initialTotalLabel === "3250 ms total"],
    ["cueStepEditorOpen", () => stats.stepEditorOpen],
    ["cueStepDuplicateAndAddApplied", () => stats.stepCount === 5],
    ["cueStepFadeEditAndReorderApplied", () => JSON.stringify(stats.stepFadeValues) === JSON.stringify([250, 375, 500, 1000, 1000])],
    ["cueStepHoldsPreserved", () => JSON.stringify(stats.stepHoldValues) === JSON.stringify([750, 750, 500, 250, 0])],
    ["cueStepEditedTotal", () => stats.stepTotalLabel === "5375 ms total"],
    ["cueStepDerivedBeatsVisible", () => stats.stepDerivedLabel === "10.75 beats at 120.0 BPM"],
    ["cueStepAuthoredBeatsApplied", () => stats.authoredBeatsValue === 10.75],
    ["cueStepUsesInternalScrollport", () => stats.stepListOverflowY === "auto" || stats.stepListOverflowY === "scroll"],
    ["cueStepAddControlRendered", () => stats.addButtonCount === 1],
    ["cueStepDuplicateControlsRendered", () => stats.duplicateButtonCount === 5],
    ["cueStepUpControlsRendered", () => stats.upButtonCount === 5],
    ["cueStepDownControlsRendered", () => stats.downButtonCount === 5],
    ["cueStepFadeInputsRendered", () => stats.fadeInputCount === 5],
    ["cueStepHoldInputsRendered", () => stats.holdInputCount === 5],
    ["cueStepDirtySaveEnabled", () => stats.saveStepsEnabled],
    // T7: the identity color picker lives in the cue edit row.
    ["cueColorPickerPresentInCueEditRow", () => stats.cueColorInputCount >= 1],
  ];
  const checks = Object.fromEntries(conditions.map(([name, check]) => {
    try {
      return [name, Boolean(check())];
    } catch {
      return [name, false];
    }
  }));
  const failedChecks = Object.entries(checks).filter(([, passed]) => !passed).map(([name]) => name);
  return {
    label: `cue-recall-${viewport.width}x${viewport.height}`,
    passed: failedChecks.length === 0,
    checks,
    failedChecks,
    containment,
    cueStoreRoute,
    stepExercise,
    stats,
  };
}

async function runCueNodeGraphViewport(client, viewport) {
  await openCueFixture(client, viewport, "cue-node-graph");
  const allScope = await client.evaluate(`(() => {
    const root = document.querySelector('[data-scene-settings]');
    const form = root?.querySelector('[data-cue-update-source-form]');
    const update = root?.querySelector('.cueUpdateLook');
    return {
      scope: form?.querySelector('select')?.value ?? '',
      updateDisabled: Boolean(update?.disabled),
      scopeErrorCount: form?.querySelectorAll('.cueScopeHint.invalid').length ?? 0,
    };
  })()`);
  await selectVisibleOption(client, "[data-cue-update-source-form] select", "video");
  await sleep(120);
  const containment = await measure(client, `cue-node-graph-${viewport.width}x${viewport.height}`);
  const videoScope = await client.evaluate(`(() => {
    const root = document.querySelector('[data-scene-settings]');
    const form = root?.querySelector('[data-cue-update-source-form]');
    const update = root?.querySelector('.cueUpdateLook');
    const previewStats = [...(root?.querySelectorAll('[data-cue-update-source-tools] .cuePreviewStats > span > strong') ?? [])]
      .map((node) => Number((node.textContent || '').trim()));
    return {
      scope: form?.querySelector('select')?.value ?? '',
      updateDisabled: Boolean(update?.disabled),
      scopeErrorCount: form?.querySelectorAll('.cueScopeHint.invalid').length ?? 0,
      graphCount: previewStats[4] ?? 0,
    };
  })()`);
  const passed = Boolean(
    hasNoOuterOverflow(containment) &&
    allScope.scope === "all" &&
    !allScope.updateDisabled &&
    allScope.scopeErrorCount === 0 &&
    videoScope.scope === "video" &&
    !videoScope.updateDisabled &&
    videoScope.scopeErrorCount === 0 &&
    videoScope.graphCount === 1
  );
  return { label: `cue-node-graph-${viewport.width}x${viewport.height}`, passed, containment, allScope, videoScope };
}

